import{_ as i,l as o,o as e,c as l,v as r,p as s,x as t,d,i as h,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"另类风险溢价 ARP","description":"","frontmatter":{"title":"另类风险溢价 ARP","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alternative-risk-premia.md","filePath":"quant/alternative-risk-premia.md","lastUpdated":1789023840000}'),p={name:"quant/alternative-risk-premia.md"};function m(E,a,u,c,B,P){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="另类风险溢价-arp" tabindex="-1">另类风险溢价 ARP <a class="header-anchor" href="#另类风险溢价-arp" aria-label="Permalink to &quot;另类风险溢价 ARP&quot;">​</a></h1><div class="epigraph"><p>把价值、动量、套息、趋势写成跨资产、规则化、可做多空的风险溢价，产品名可以叫 ARP；经济学上它们仍是承担某种状态的补偿，或是尚未被费用吃掉的异象。</p><footer>—— Asness, Moskowitz and Pedersen, Value and Momentum Everywhere, Journal of Finance, 2013；Carry 见 Koijen 等, JFE, 2018</footer></div><p><a href="/quant/short-vol-tail">上一课</a>把短波动标成一类可打包的溢价。另类风险溢价（ARP）的缺口是<strong>整张地图</strong>：价值、动量、<a href="/quant/carry-everywhere">跨资产 Carry</a>、<a href="/quant/tsmom">趋势</a>、低风险、以及短波动，如何与股票多空、宏观、RV 分工。主干 <a href="/quant/value-momentum-everywhere">价值与动量无处不在</a>、<a href="/quant/risk-parity">风险平价</a> 已写构造。本课只定策略族：ARP 是规则化的风险预算，不是「对冲基金 alpha」的新名字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机构把「另类」卖成低相关的第三条收益。实现上，ARP 组合在风险偏好冲击里相关升高：动量崩、价值修复、短波动缺口可以叠在同一季。问题是分类：哪些腿有风险补偿叙事（Carry 在崩溃状态差），哪些更像行为或结构（指数纳入、拥挤），哪些只是杠杆过的市场 beta。不要用 <a href="/quant/capm">CAPM</a> 的截面回归把所有 ARP 再「检验」一遍——主干已经做过因子实证；本课问的是<strong>产品层如何分桶与约束</strong>。</p><p>与股票多空：学术 HML/动量是 ARP 的股票实现；产品还要期货、FX、商品腿，约束在保证金与展期，不在借券。与宏观：系统宏观往往就是趋势+套息，应承认重叠，勿双边计提容量。</p><h3 id="规则化不等于可容量无限" tabindex="-1">规则化不等于可容量无限 <a class="header-anchor" href="#规则化不等于可容量无限" aria-label="Permalink to &quot;规则化不等于可容量无限&quot;">​</a></h3><p>把信号写成透明规则，方便复制，也方便拥挤。ARP 的衰减来自费用、冲击与同质杠杆，见后课策略生命周期。风险平价是配权引擎，不是又一个溢价；它放大 ARP 也放大同步去杠杆。</p><p><span class="marginnote">Litterman 的风险预算语言（热点与对冲）比「再找一个新因子」更适合 ARP 组合：先看谁贡献主动风险，再决定要不要那一腿的溢价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单：价值、动量、Carry、趋势、低 beta、短波动。每条腿：资产类、再平衡、成本、危机情景。组合：风险平价或等风险贡献，对冲掉不需要的市场 beta。报告：腿的相关矩阵用体制切片，不用全样本一个数。与 <a href="/quant/black-litterman">Black–Litterman</a> 的衔接：主观观点应加在溢价均值上，而不是改信号定义。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>跨资产共同溢价意味着共同状态变量：增长、通胀、流动性、风险偏好。规则化收获的是状态补偿的可交易投影。产品层把投影切成可销售的份额，同时制造拥挤。短波动是其中凸性最差的一条，不能用价值的回撤经验去标定它的保证金。</p>',13)),(e(),s(A,null,{default:t(()=>[h(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Prem%5B%22%E4%BB%B7%E5%80%BC%20%E5%8A%A8%E9%87%8F%20Carry%20%E8%B6%8B%E5%8A%BF%20%E7%9F%AD%E6%B3%A2%22%5D%20--%3E%20Rules%5B%22%E8%A7%84%E5%88%99%E5%8C%96%E5%A4%9A%E7%A9%BA%22%5D%0A%20%20Rules%20--%3E%20Alloc%5B%22%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%20%E5%B9%B3%E4%BB%B7%E6%88%96%20BL%20%E8%A7%82%E7%82%B9%22%5D%0A%20%20Crowd%5B%22%E5%8F%AF%E5%A4%8D%E5%88%B6%22%5D%20--%3E%20Alloc%0A%20%20Alloc%20--%3E%20Crisis%5B%22%E5%81%8F%E5%A5%BD%E5%86%B2%E5%87%BB%E4%B8%8B%E7%9B%B8%E5%85%B3%E5%8D%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ARP 不是法律上的「另类投资」定义。本课不把私募、实物放进同一张期货溢价表。评价必须扣费、扣展期、扣危机月。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ARP 是规则化的跨资产溢价桶，不是新的 alpha 物种。</li><li>与宏观、股票多空有重叠，容量不要双边计算。</li><li>短波动与价值不可用同一套回撤经验。</li><li>出处：Asness, Moskowitz and Pedersen, <em>JF</em>, 2013；Koijen, Moskowitz, Pedersen and Vrugt, <em>JFE</em>, 2018；风险预算对照 Litterman, Hot Spots and Hedges。</li></ul>',4))])}const q=i(p,[["render",m]]);export{f as __pageData,q as default};
